#include <iostream>
#include <string>

int main() {
    std::string s1, s2;
    std::cin >> s1 >> s2;

    int l1 = s1.length();
    int l2 = s2.length();
    int c = 0;

    for (int j = 0, k = l2 - 1; j < l1 && k >= 0; j++, k--) {
        if (s1[j] == s2[k]) {
            c++;
        }
    }

    if (l1 == c) {
        std::cout << "YES\n";
    } else {
        std::cout << "NO\n";
    }

    return 0;
}

